		long namespaceId = Varint.readUnsigned(encodedPredicate);
		assertThat(ValueIds.getIdType(namespaceId)).isEqualTo(ValueIds.T_PTR);
		removeReverseMappingAndMark(namespaceId, 14);
		removeReverseMappingAndMark(literalId, 15);

