	@Test
	void reopensLegacyStoreWithManyNamedContextsWithoutGrowingValidationStack() throws Exception {
		var values = SimpleValueFactory.getInstance();
		var subject = values.createIRI("urn:context:subject");
		var predicate = values.createIRI("urn:context:predicate");
		var object = values.createLiteral("named graph");
		int contextCount = 12_000;
		SailRepository initial = repository();
		initial.init();
		try (var connection = initial.getConnection()) {
			connection.begin();
			for (int i = 0; i < contextCount; i++) {
				connection.add(subject, predicate, object, values.createIRI("urn:context:" + i));
			}
			connection.commit();
		} finally {
			initial.shutDown();
		}

		SailRepository reopened = repository();
		reopened.init();
		try (var connection = reopened.getConnection()) {
			assertThat(connection.size()).isEqualTo(contextCount);
			assertThat(connection.hasStatement(subject, predicate, object, true,
					values.createIRI("urn:context:" + (contextCount - 1)))).isTrue();
		} finally {
			reopened.shutDown();
		}
	}

